(function(root,factory){if(typeof module==='object'&&module.exports)module.exports=factory();else root.NoteSchema=factory();})(typeof window==='undefined'?globalThis:window,function(){
  'use strict';
  const subjects=['chemistry','biology','math','physics','chinese','english'];
  const topics={"math":["集合与常用逻辑用语","不等式","函数与导数","三角函数与解三角形","数列","立体几何与空间向量","平面解析几何（直线、圆、圆锥曲线）","概率与统计","复数、平面向量","排列组合与二项式定理","新定义与创新题型"],"physics":["运动的描述与匀变速直线运动","相互作用（受力分析）","牛顿运动定律","曲线运动（平抛、圆周）","万有引力与航天","机械能守恒定律","动量与动量守恒","电场","电路","磁场","电磁感应","交变电流","热学（分子动理论、气体、热力学定律）","机械波与光学","原子物理（原子结构、原子核、波粒二象性）","物理实验"],"chemistry":["物质的量与化学计量","离子反应","氧化还原反应","元素化合物（钠、铝、铁、铜、氯、硫、氮、碳等）","物质结构与性质","化学反应与能量（热化学）","化学反应速率与化学平衡","水溶液中的离子平衡（电离、水解、沉淀溶解）","电化学","有机化学基础","化学实验","化学与工业流程"],"chinese":[],"english":[],"biology":["细胞的分子组成","细胞的结构与物质运输","酶、ATP与细胞代谢（呼吸、光合）","细胞的增殖、分化、衰老与凋亡","遗传的细胞基础（减数分裂）","遗传的分子基础（DNA、基因表达）","遗传规律与伴性遗传","变异、育种与人类遗传病","生物进化","稳态与调节（内环境、神经、体液、免疫、植物激素）","生物与环境（种群、群落、生态系统）","生物技术与工程（基因、细胞、发酵工程）","生物学实验与探究"]};
  const limits={question:20000,answer:10000,explanation:20000,notes:10000,equation:2000,equationPlain:2000};
  const imageName=/^[a-zA-Z0-9_-]+\.(png|jpe?g|webp)$/i;
  function errors(q){const out=[];if(!q||typeof q!=='object'||Array.isArray(q))return ['题目必须是一个 JSON 对象'];if(!subjects.includes(q.subject))out.push('学科必须为 chemistry、biology、math、physics、chinese 或 english');if(typeof q.id!=='string'||!/^[-a-zA-Z0-9_]{1,80}$/.test(q.id))out.push('id 只能含英文字母、数字、连字符和下划线，长度 1—80');if(typeof q.topic!=='string'||!q.topic.trim()||q.topic.length>60)out.push('专题必填，最多 60 字');if(typeof q.topic==='string'&&subjects.includes(q.subject)&&!topics[q.subject].includes(q.topic))out.push('题目类别必须从该学科规定的类别中选择');if(typeof q.question!=='string'||!q.question.trim())out.push('题目不能为空');for(const[k,n]of Object.entries(limits))if(q[k]!==undefined&&(typeof q[k]!=='string'||q[k].length>n))out.push(k+' 必须是字符串，且不超过 '+n+' 字');if(q.mastered!==undefined&&typeof q.mastered!=='boolean')out.push('mastered 必须为布尔值');if(q.images!==undefined){if(!Array.isArray(q.images)||q.images.length>20)out.push('images 必须为最多 20 张的数组');else for(const image of q.images){if(!image||typeof image!=='object'||!imageName.test(image.file||'')||typeof image.alt!=='string'||image.alt.length>200)out.push('题图需有安全文件名和不超过 200 字的说明');}}return out;}
  function normalize(q){const result={id:q.id,subject:q.subject,topic:q.topic.trim()};for(const k of Object.keys(limits))result[k]=q[k]||'';result.images=(q.images||[]).map(image=>({file:image.file,alt:image.alt}));result.mastered=!!q.mastered;result.demo=!!q.demo;result.createdAt=typeof q.createdAt==='string'?q.createdAt:new Date().toISOString();result.updatedAt=typeof q.updatedAt==='string'?q.updatedAt:result.createdAt;return result;}
  function settings(input={}){return {paper:input.paper==='A4'?'A4':'B5',columns:input.columns===1?1:2,compact:input.compact!==false,answers:input.answers!==false};}
  return {errors,normalize,settings,subjects,topics,limits};
});
